contracts/DriverApplicationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title DriverApplicationRegistry
 * @dev A smart contract for storing and verifying DOT driver applications on the blockchain
 * @author DriverAppChain
 */
contract DriverApplicationRegistry is Ownable, Pausable, ReentrancyGuard, AccessControl {
    struct PersonalInfo {
        string firstName;
        string lastName;
        string middleName;
        string email;
        string phone;
        string dateOfBirth;
        string streetAddress;
        string city;
        string state;
        string zipCode;
        string country;
    }
    
    struct CDLInfo {
        string cdlNumber;
        string cdlClass;
        string cdlState;
        string cdlExpirationDate;
        string[] endorsements;
        string restrictions;
    }
    
    struct EmploymentHistory {
        string companyName;
        string position;
        string startDate;
        string endDate;
        string supervisorName;
        string supervisorPhone;
        string reasonForLeaving;
        bool canContact;
    }
    
    struct Violation {
        string date;
        string violation;
        string location;
        string fine;
        string points;
    }
    
    struct Accident {
        string date;
        string location;
        string description;
        string injuries;
        string fatalities;
        string propertyDamage;
    }
    
    struct DrivingRecord {
        Violation[] violations;
        Accident[] accidents;
    }
    
    struct MedicalInfo {
        string medicalExamDate;
        string medicalExamExpiration;
        string medicalExaminerName;
        string medicalExaminerPhone;
        string medicalExaminerAddress;
        bool hasDisqualifyingConditions;
        string disqualifyingConditions;
        bool hasCorrectiveLenses;
        bool hasHearingAid;
        bool hasProstheticDevice;
    }
    
    struct DrugAlcoholTesting {
        string lastTestDate;
        string testResult;
        string testingCompany;
        string testingCompanyPhone;
        string testingCompanyAddress;
    }
    
    struct TrainingRecord {
        string trainingType;
        string trainingDate;
        string trainingCompany;
        string certificationNumber;
        string expirationDate;
    }
    
    struct EquipmentExperience {
        uint256 yearsExperience;
        uint256 milesDriven;
    }
    
    struct SpecializedEquipment {
        string equipmentType;
        uint256 yearsExperience;
        uint256 milesDriven;
    }
    
    struct EquipmentTypes {
        EquipmentExperience straightTruck;
        EquipmentExperience tractorTrailer;
        EquipmentExperience tractorTwoTrailers;
        SpecializedEquipment[] specializedEquipment;
    }
    
    struct SpecialSkills {
        string[] skills;
    }
    
    struct DrivingExperience {
        EquipmentTypes equipmentTypes;
        SpecialSkills specialSkills;
    }
    
    struct SafetyAccident {
        string date;
        string accidentType;
        bool commercialVehicle;
        bool dotRecordable;
        bool atFault;
        bool citationIssued;
        string description;
    }
    
    struct SafetyViolation {
        string date;
        string violation;
        string location;
        string fineAmount;
        string points;
    }
    
    struct ComplianceQuestions {
        bool fmcsrDisqualification;
        bool duiDwi;
        bool positiveDrugTest;
        bool licenseSuspension;
        bool accidentHistory;
        bool violationHistory;
    }
    
    struct SafetyCompliance {
        SafetyAccident[] accidents;
        SafetyViolation[] violations;
        ComplianceQuestions complianceQuestions;
    }
    
    struct Reference {
        string name;
        string relationship;
        string phone;
        string email;
        string company;
        string yearsKnownValue;
    }
    
    struct DriverApplication {
        address owner;
        PersonalInfo personalInfo;
        CDLInfo cdlInfo;
        EmploymentHistory[] employmentHistory;
        DrivingRecord drivingRecord;
        MedicalInfo medicalInfo;
        DrugAlcoholTesting drugAlcoholTesting;
        TrainingRecord[] trainingRecords;
        DrivingExperience drivingExperience;
        SafetyCompliance safetyCompliance;
        Reference[] references;
        bool isVerified;
        bool isComplete;
        uint256 timestamp;
        uint256 lastUpdated;
        string applicationHash; // SHA-256 hash of the complete application data
    }
    
    struct Verification {
        address verifier;
        bool verified;
        string verificationHash;
        uint256 timestamp;
        string notes;
        string[] verifiedSections; // Which sections were verified
    }
    
    // Roles
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant DOT_INSPECTOR_ROLE = keccak256("DOT_INSPECTOR_ROLE");
    
    // State variables
    mapping(uint256 => DriverApplication) public applications;
    mapping(address => uint256[]) public userApplications;
    mapping(uint256 => Verification) public verifications;
    mapping(string => bool) public usedApplicationHashes;
    
    uint256 public applicationCount;
    
    // Events
    event ApplicationSubmitted(
        uint256 indexed applicationId, 
        address indexed owner, 
        string applicationHash
    );
    
    event ApplicationUpdated(
        uint256 indexed applicationId, 
        address indexed owner, 
        string newApplicationHash
    );
    
    event ApplicationVerified(
        uint256 indexed applicationId, 
        address indexed verifier, 
        bool verified,
        string[] verifiedSections
    );
    
    event VerifierAdded(address indexed verifier);
    event VerifierRemoved(address indexed verifier);
    event DOTInspectorAdded(address indexed inspector);
    event DOTInspectorRemoved(address indexed inspector);
    
    // Modifiers
    modifier applicationExists(uint256 _applicationId) {
        require(_applicationId > 0 && _applicationId <= applicationCount, "Not exist");
        _;
    }
    
    constructor() Ownable(msg.sender) {
        // Set up roles
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(VERIFIER_ROLE, msg.sender);
        _grantRole(DOT_INSPECTOR_ROLE, msg.sender);
    }
    
    /**
     * @dev Submit a new driver application to the registry
     * @param _applicationHash SHA-256 hash of the complete application data
     * @param _personalInfo Personal information struct
     * @param _cdlInfo CDL information struct
     * @param _employmentHistory Array of employment history
     * @param _drivingRecord Driving record struct
     * @param _medicalInfo Medical information struct
     * @param _drugAlcoholTesting Drug/alcohol testing information
     * @param _trainingRecords Array of training records
     * @param _drivingExperience Driving experience struct
     * @param _safetyCompliance Safety compliance struct
     * @param _references Array of references
     * @return applicationId The ID of the created application
     */
    function submitApplication(
        string memory _applicationHash,
        PersonalInfo memory _personalInfo,
        CDLInfo memory _cdlInfo,
        EmploymentHistory[] memory _employmentHistory,
        DrivingRecord memory _drivingRecord,
        MedicalInfo memory _medicalInfo,
        DrugAlcoholTesting memory _drugAlcoholTesting,
        TrainingRecord[] memory _trainingRecords,
        DrivingExperience memory _drivingExperience,
        SafetyCompliance memory _safetyCompliance,
        Reference[] memory _references
    ) external whenNotPaused nonReentrant returns (uint256) {
        require(bytes(_applicationHash).length > 0, "Hash required");
        require(!usedApplicationHashes[_applicationHash], "Hash used");
        require(bytes(_personalInfo.email).length > 0, "Email required");
        require(bytes(_personalInfo.firstName).length > 0, "First name required");
        require(bytes(_personalInfo.lastName).length > 0, "Last name required");
        
        applicationCount++;
        uint256 applicationId = applicationCount;
        
        // Store the application data
        DriverApplication storage app = applications[applicationId];
        app.owner = msg.sender;
        app.personalInfo = _personalInfo;
        app.cdlInfo = _cdlInfo;
        app.drivingRecord = _drivingRecord;
        app.medicalInfo = _medicalInfo;
        app.drugAlcoholTesting = _drugAlcoholTesting;
        app.drivingExperience = _drivingExperience;
        app.safetyCompliance = _safetyCompliance;
        app.isVerified = false;
        app.isComplete = true;
        app.timestamp = block.timestamp;
        app.lastUpdated = block.timestamp;
        app.applicationHash = _applicationHash;
        
        // Handle arrays separately
        for (uint256 i = 0; i < _employmentHistory.length; i++) {
            app.employmentHistory.push(_employmentHistory[i]);
        }
        
        for (uint256 i = 0; i < _trainingRecords.length; i++) {
            app.trainingRecords.push(_trainingRecords[i]);
        }
        
        for (uint256 i = 0; i < _references.length; i++) {
            app.references.push(_references[i]);
        }
        
        userApplications[msg.sender].push(applicationId);
        usedApplicationHashes[_applicationHash] = true;
        
        emit ApplicationSubmitted(applicationId, msg.sender, _applicationHash);
        return applicationId;
    }
    
    /**
     * @dev Update an existing application (only owner can update)
     * @param _applicationId ID of the application to update
     * @param _newApplicationHash New application hash
     * @param _personalInfo Updated personal information
     * @param _cdlInfo Updated CDL information
     * @param _employmentHistory Updated employment history
     * @param _drivingRecord Updated driving record
     * @param _medicalInfo Updated medical information
     * @param _drugAlcoholTesting Updated drug/alcohol testing
     * @param _trainingRecords Updated training records
     * @param _drivingExperience Updated driving experience
     * @param _safetyCompliance Updated safety compliance
     * @param _references Updated references
     */
    function updateApplication(
        uint256 _applicationId,
        string memory _newApplicationHash,
        PersonalInfo memory _personalInfo,
        CDLInfo memory _cdlInfo,
        EmploymentHistory[] memory _employmentHistory,
        DrivingRecord memory _drivingRecord,
        MedicalInfo memory _medicalInfo,
        DrugAlcoholTesting memory _drugAlcoholTesting,
        TrainingRecord[] memory _trainingRecords,
        DrivingExperience memory _drivingExperience,
        SafetyCompliance memory _safetyCompliance,
        Reference[] memory _references
    ) external whenNotPaused nonReentrant applicationExists(_applicationId) {
        DriverApplication storage application = applications[_applicationId];
        require(application.owner == msg.sender, "Not owner");
        require(bytes(_newApplicationHash).length > 0, "Hash required");
        require(!usedApplicationHashes[_newApplicationHash], "Hash used");
        
        // Remove old hash from used hashes
        usedApplicationHashes[application.applicationHash] = false;
        
        // Update application
        application.personalInfo = _personalInfo;
        application.cdlInfo = _cdlInfo;
        application.drivingRecord = _drivingRecord;
        application.medicalInfo = _medicalInfo;
        application.drugAlcoholTesting = _drugAlcoholTesting;
        application.drivingExperience = _drivingExperience;
        application.safetyCompliance = _safetyCompliance;
        application.isVerified = false; // Reset verification status
        application.lastUpdated = block.timestamp;
        application.applicationHash = _newApplicationHash;
        
        // Clear existing arrays and repopulate
        delete application.employmentHistory;
        for (uint256 i = 0; i < _employmentHistory.length; i++) {
            application.employmentHistory.push(_employmentHistory[i]);
        }
        
        delete application.trainingRecords;
        for (uint256 i = 0; i < _trainingRecords.length; i++) {
            application.trainingRecords.push(_trainingRecords[i]);
        }
        
        delete application.references;
        for (uint256 i = 0; i < _references.length; i++) {
            application.references.push(_references[i]);
        }
        
        // Add new hash to used hashes
        usedApplicationHashes[_newApplicationHash] = true;
        
        emit ApplicationUpdated(_applicationId, msg.sender, _newApplicationHash);
    }
    
    /**
     * @dev Verify a driver application
     * @param _applicationId ID of the application to verify
     * @param _verified Whether the application is verified
     * @param _verificationHash Hash of verification data
     * @param _notes Verification notes
     * @param _verifiedSections Which sections were verified
     */
    function verifyApplication(
        uint256 _applicationId,
        bool _verified,
        string memory _verificationHash,
        string memory _notes,
        string[] memory _verifiedSections
    ) external onlyRole(VERIFIER_ROLE) whenNotPaused nonReentrant applicationExists(_applicationId) {
        DriverApplication storage application = applications[_applicationId];
        
        verifications[_applicationId] = Verification({
            verifier: msg.sender,
            verified: _verified,
            verificationHash: _verificationHash,
            timestamp: block.timestamp,
            notes: _notes,
            verifiedSections: _verifiedSections
        });
        
        application.isVerified = _verified;
        
        emit ApplicationVerified(_applicationId, msg.sender, _verified, _verifiedSections);
    }
    
    /**
     * @dev Get all applications for a user
     * @param _user User address
     * @return Array of application IDs
     */
    function getUserApplications(address _user) external view returns (uint256[] memory) {
        return userApplications[_user];
    }
    
    /**
     * @dev Get application details
     * @param _applicationId Application ID
     * @return DriverApplication struct
     */
    function getApplication(uint256 _applicationId) external view applicationExists(_applicationId) returns (DriverApplication memory) {
        return applications[_applicationId];
    }
    
    /**
     * @dev Get verification details
     * @param _applicationId Application ID
     * @return Verification struct
     */
    function getVerification(uint256 _applicationId) external view applicationExists(_applicationId) returns (Verification memory) {
        return verifications[_applicationId];
    }
    
    /**
     * @dev Get all verified applications
     * @return Array of verified application IDs
     */
    function getVerifiedApplications() external view returns (uint256[] memory) {
        uint256[] memory verifiedApplications = new uint256[](applicationCount);
        uint256 count = 0;
        
        for (uint256 i = 1; i <= applicationCount; i++) {
            if (applications[i].isVerified) {
                verifiedApplications[count] = i;
                count++;
            }
        }
        
        // Resize array to actual count
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            result[i] = verifiedApplications[i];
        }
        
        return result;
    }
    
    // Admin functions
    function addVerifier(address _verifier) external onlyRole(ADMIN_ROLE) {
        _grantRole(VERIFIER_ROLE, _verifier);
        emit VerifierAdded(_verifier);
    }
    
    function removeVerifier(address _verifier) external onlyRole(ADMIN_ROLE) {
        _revokeRole(VERIFIER_ROLE, _verifier);
        emit VerifierRemoved(_verifier);
    }
    
    function addDOTInspector(address _inspector) external onlyRole(ADMIN_ROLE) {
        _grantRole(DOT_INSPECTOR_ROLE, _inspector);
        emit DOTInspectorAdded(_inspector);
    }
    
    function removeDOTInspector(address _inspector) external onlyRole(ADMIN_ROLE) {
        _revokeRole(DOT_INSPECTOR_ROLE, _inspector);
        emit DOTInspectorRemoved(_inspector);
    }
    
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }
    
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
    
    // Utility functions
    function isVerifier(address _account) external view returns (bool) {
        return hasRole(VERIFIER_ROLE, _account);
    }
    
    function isAdmin(address _account) external view returns (bool) {
        return hasRole(ADMIN_ROLE, _account);
    }
    
    function isDOTInspector(address _account) external view returns (bool) {
        return hasRole(DOT_INSPECTOR_ROLE, _account);
    }
    
    /**
     * @dev Check if an application hash has been used
     * @param _hash The hash to check
     * @return Whether the hash has been used
     */
    function isApplicationHashUsed(string memory _hash) external view returns (bool) {
        return usedApplicationHashes[_hash];
    }
}

